import {initialState,uid,today,validateState,toKg,fromKg,displayLoad} from './model.js';
import {EXERCISES,GOALS,MUSCLES,library,findExercise,substitutions} from './exercises.js';
import {recommend,exposures,working,goalRange} from './engine.js';
import {generatePlans,makeDraft} from './planner.js';
import {summary,volume,weekStart,muscleSets,weightTrend,strengthPoints,achievements,sessionSets} from './analytics.js';
import {openDB,loadState,saveState,getPhoto,putPhoto,deletePhoto,restoreState} from './storage.js';
import {download,exportBackup,parseBackup,exportCSV} from './backup.js';
import {esc,icon,button,field,options,empty,chart} from './ui.js';
import {prepareLegacyImport} from './legacy-import.js';
let state=initialState(),queue=Promise.resolve(),route=location.hash.slice(1)||'workout',previous=null,imported=null,photoURLs=[],restEnd=0,restInterval;
const app=document.querySelector('#app');
const fmt=n=>new Intl.NumberFormat(undefined,{maximumFractionDigits:1}).format(n);
const unit=()=>state.profile.unit;
const load=kg=>displayLoad(kg,unit());
const dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric'});
const metric=(label,value,sub='')=>`<div class="metric"><span>${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(sub)}</small></div>`;
const title=(eyebrow,heading,desc='',right='')=>`<header class="page-head"><div><p class="eyebrow">${esc(eyebrow)}</p><h1>${esc(heading)}</h1>${desc?`<p class="subtitle">${esc(desc)}</p>`:''}</div>${right}</header>`;
function notify(message,error=false){let box=document.querySelector('#toast');if(!box){box=document.createElement('div');box.id='toast';box.setAttribute('role','status');document.body.append(box);}box.className=error?'toast error':'toast';box.textContent=message;box.hidden=false;clearTimeout(box.timer);box.timer=setTimeout(()=>{box.hidden=true;},error?14000:4500);}
function commit(fn,{draw=true,undo=false}={}){const operation=queue.then(async()=>{const next=structuredClone(state);fn(next);if(next.profile){next.unlocks=[...new Set([...next.unlocks,...achievements(next).filter(a=>a.unlocked).map(a=>a.id)])];}validateState(next);await saveState(next);previous=undo?structuredClone(state):null;state=next;if(draw)render();return state;});queue=operation.catch(e=>notify('Could not save: '+e.message,true));return operation;}
function go(to){location.hash=to;if(route===to)render();}
window.addEventListener('hashchange',()=>{route=location.hash.slice(1)||'workout';render();window.scrollTo(0,0);});
window.addEventListener('pageshow',e=>{if(e.persisted)location.reload();});
window.addEventListener('offline',()=>notify('Offline. Your journal still works on this device.'));
window.addEventListener('beforeunload',e=>{if(pendingWrites){e.preventDefault();e.returnValue='';}});
let pendingWrites=0;
function queued(fn,opts){pendingWrites++;return commit(fn,opts).finally(()=>pendingWrites--);}
function closeDialog(){document.querySelector('dialog')?.close();document.querySelector('dialog')?.remove();}
function dialog(heading,content){closeDialog();const d=document.createElement('dialog');d.innerHTML=`<div class="dialog-head"><h2>${esc(heading)}</h2>${button(icon('close'),'close','icon-button','aria-label="Close dialog"')}</div>${content}`;document.body.append(d);d.showModal();d.addEventListener('close',()=>d.remove(),{once:true});}
const confirmAction=(heading,text,action,attrs='')=>dialog(heading,`<p>${esc(text)}</p><div class="actions">${button('Cancel','close','secondary')}${button('Confirm',action,'danger',attrs)}</div>`);
function render(){photoURLs.forEach(URL.revokeObjectURL);photoURLs=[];if(!state.profile){onboarding();return;}
 const nav=[['workout','Workout'],['programs','Programs'],['progress','Gains'],['body','Body'],['settings','Settings']];
 app.innerHTML=`<aside class="sidebar"><a href="#workout" class="brand"><span class="brand-icon">${icon('workout')}</span>gym bro<span class="brand-dot">.</span></a><p class="sidebar-caption">A LITTLE STRONGER, EVERY DAY</p><nav aria-label="Main navigation">${nav.map(([id,label])=>`<a href="#${id}" class="nav-link ${route===id?'active':''}" ${route===id?'aria-current="page"':''}>${icon(id)}<span>${label}</span>${id===route?'<span class="nav-dot"></span>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="privacy">${icon('shield')}<div><strong>Your space. Your data.</strong><small>Stored on this device</small></div></div><a href="#settings" class="profile-link"><span class="avatar">${esc((state.profile.name||'You').slice(0,1).toUpperCase())}</span><span><strong>${esc(state.profile.name||'Your profile')}</strong><small>${esc(GOALS[state.profile.goal])}</small></span>${icon('chevron')}</a></div></aside><div class="workspace"><header class="topbar"><span class="topbar-label">YOUR PERSONAL TRAINING SPACE</span><span class="local-badge"><i></i> Local & private</span></header><main id="main" tabindex="-1">${({workout:workoutView,programs:programsView,progress:progressView,body:bodyView,settings:settingsView,history:historyView}[route]||workoutView)()}</main><footer class="app-footer">Built for the long game.<span>Progress is personal. Keep showing up.</span></footer></div><nav class="mobile-nav" aria-label="Mobile navigation">${nav.map(([id,label])=>`<a href="#${id}" ${route===id?'aria-current="page"':''}>${icon(id)}<span>${label}</span></a>`).join('')}</nav>`;
 if(route==='body')hydratePhotos();
}
function profileFields(p={},onboard=false){return `${field('Your name',`<input name="name" maxlength="60" autocomplete="given-name" value="${esc(p.name||'')}" placeholder="What should we call you?">`)}${field('Primary goal',`<select name="goal">${options(GOALS,p.goal||'hypertrophy')}</select>`)}<div class="form-grid">${field('Experience',`<select name="experience">${options({beginner:'Getting started',intermediate:'Training regularly',experienced:'Experienced lifter'},p.experience||'beginner')}</select>`)}${field('Sessions per week',`<input name="days" type="number" min="1" max="7" step="1" required value="${p.days||3}">`)}${field('Session length (minutes)',`<input name="minutes" type="number" min="15" max="150" step="5" required value="${p.minutes||45}">`)}${field('Training structure',`<select name="split">${options({full:'Full body',upperlower:'Upper / lower',ppl:'Push / pull / legs',custom:'Custom / manual'},p.split||'full')}</select>`)}${field('Display units',`<select name="unit" data-current-unit="${p.unit||'kg'}">${options({kg:'Kilograms · centimeters',lb:'Pounds · inches'},p.unit||'kg')}</select>`)}${field('Equipment increment (in selected units)',`<input name="increment" type="number" min="0.25" max="50" step="any" required value="${p.incrementKg?displayLoad(p.incrementKg,p.unit):2.5}">`,'Smallest available total-load increment; dumbbell loads are per dumbbell.')}</div><fieldset><legend>Available equipment</legend><div class="chips">${Object.entries({barbell:'Barbell',dumbbell:'Dumbbells',machine:'Machines',cable:'Cables',bodyweight:'Bodyweight'}).map(([v,l])=>`<label class="check-chip"><input name="equipment" type="checkbox" value="${v}" ${(p.equipment||['dumbbell','bodyweight']).includes(v)?'checked':''}>${l}</label>`).join('')}</div></fieldset><details><summary>Personalize a little more <span>Optional</span></summary><div class="form-grid">${field('Secondary goal',`<select name="secondaryGoal"><option value="">None</option>${options(GOALS,p.secondaryGoals?.[0])}</select>`)}${field('Muscle priority',`<select name="priority"><option value="">Balanced</option>${MUSCLES.map(m=>`<option ${p.priorities?.includes(m)?'selected':''}>${m}</option>`).join('')}</select>`)}</div><fieldset><legend>Preferred training days (optional)</legend><div class="chips">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<label class="check-chip"><input type="checkbox" name="trainingDays" value="${d}" ${p.trainingDays?.includes(d)?'checked':''}>${d}</label>`).join('')}</div></fieldset>${field('Personal exercise restrictions or notes',`<textarea name="restrictions" maxlength="1000" placeholder="Notes for you to review before training">${esc(p.restrictions||'')}</textarea>`,'These notes are reminders, not automatically interpreted medical constraints. Exclude specific exercises below.')}${field('Exclude exercises',`<select name="excluded" multiple size="5">${library(state).map(e=>`<option value="${e.id}" ${p.excluded?.includes(e.id)?'selected':''}>${esc(e.name)}</option>`).join('')}</select>`)}<label class="toggle"><input type="checkbox" name="auto" ${p.auto!==false?'checked':''}>Enable editable progression suggestions</label><label class="toggle"><input type="checkbox" name="timer" ${p.timer?'checked':''}>Optional rest timer after a completed set</label>${field('Rest timer (seconds)',`<input name="restSeconds" type="number" min="15" max="600" required value="${p.restSeconds||120}">`)}</details>`;}
function onboarding(){app.innerHTML=`<main id="main" class="onboarding"><div class="welcome-brand"><span class="brand-icon">${icon('workout')}</span>gym bro.</div><div class="welcome-grid"><section class="welcome-copy"><p class="eyebrow">TRAIN WITH INTENTION</p><h1>Your training.<br>A little stronger.</h1><p>A simple place to log the work, understand your progress, and know what to try next.</p><div class="welcome-art" aria-hidden="true"><div class="barbell">${icon('workout')}</div><span class="art-tag">CONSISTENCY OVER COMPLEXITY</span></div><div class="welcome-points"><span>${icon('shield')}Private by default</span><span>${icon('bolt')}Works offline</span><span>${icon('progress')}Progress you can explain</span></div></section><section class="welcome-form"><p class="eyebrow">MAKE IT YOURS</p><h2>Meet your next chapter.</h2><p>Start with the essentials. You can change everything later.</p><form id="onboard-form">${profileFields()}<button class="primary wide" type="submit">Build my training space ${icon('arrow')}</button><small class="muted">No account. No subscriptions. Just you and the work.</small></form></section></div></main>`;}
function workoutView(){if(state.draft)return activeView();const start=weekStart(today());const thisWeek=state.sessions.filter(w=>w.date>=start&&w.date<=today());const all=summary(state.sessions);const name=state.profile.name?`, ${state.profile.name.split(' ')[0]}`:'';return `${title('THE WORK STARTS HERE',`Let’s get stronger${name}.`,'A good session starts with a simple plan.',`<a class="text-link" href="#history">${icon('history')}Workout history</a>`)}<div class="overview-grid"><section class="session-hero"><div class="hero-top"><span class="pill">YOUR NEXT SESSION</span><span>${icon('clock')}${state.profile.minutes} min</span></div><div class="hero-mark" aria-hidden="true">${icon('workout')}</div><p class="hero-kicker">${esc(GOALS[state.profile.goal])} · ${state.profile.days} days / week</p><h2>${esc(state.plans[0]?.name||'Your next good session')}</h2><p class="hero-desc">${state.plans[0]?`${state.plans[0].exercises.length} exercises. A clear plan. Room to make it yours.`:'Choose your exercises, find your rhythm, and make a start.'}</p><div class="hero-bottom">${button(`Start workout ${icon('arrow')}`,state.plans[0]?'start-plan':'start-empty','primary light',state.plans[0]?`data-id="${state.plans[0].id}"`:'')}<span>One set at a time.</span></div></section><section class="week-card"><div class="section-label">THIS WEEK<span>${dateLabel(start)} — today</span></div><div class="week-total">${thisWeek.length}<span>/ ${state.profile.days}<small>sessions completed</small></span></div><div class="week-days">${['M','T','W','T','F','S','S'].map((d,i)=>{const dt=new Date(start+'T12:00:00');dt.setDate(dt.getDate()+i);const key=dt.getFullYear()+'-'+String(dt.getMonth()+1).padStart(2,'0')+'-'+String(dt.getDate()).padStart(2,'0');const done=state.sessions.some(w=>w.date===key);return `<div><span class="day ${done?'done':''} ${today()===key?'today':''}" aria-label="${key}${done?', completed':''}">${done?icon('check'):d}</span><small>${dt.getDate()}</small></div>`;}).join('')}</div><p>${thisWeek.length>=state.profile.days?'Your weekly session goal is met. Make room for recovery, too.':'Make room for yourself. Consistency builds over time.'}</p></section></div><div class="metric-row">${metric('WORKOUTS',all.workouts,'All-time sessions')}${metric('WORKING SETS',fmt(all.sets),'The work you’ve put in')}${metric('REPETITIONS',fmt(all.reps),'One rep at a time')}${metric('PERSONAL MILESTONES',achievements(state).filter(a=>a.unlocked).length,'Progress worth noticing')}</div><div class="section-head"><div><p class="eyebrow">YOUR TRAINING TOOLKIT</p><h2>Show up with a plan.</h2></div><a href="#programs" class="text-link">Manage programs ${icon('arrow')}</a></div><div class="plan-grid">${state.plans.slice(0,3).map(planCard).join('')}${!state.plans.length?empty('Build your first program','A routine keeps your next session simple.',button('Create program','new-plan','secondary')):''}</div><div class="insight-strip"><span class="insight-icon">${icon('bolt')}</span><div><strong>Small steps. Real progress.</strong><p>Recommendations learn from your saved working sets. Your starting load always comes from you.</p></div><a href="#progress" class="text-link">Explore your gains ${icon('arrow')}</a></div>`;}
function planCard(p){return `<article class="plan-card"><div class="plan-card-top"><span class="plan-symbol">${icon('workout')}</span><span class="muted">${p.exercises.length} exercises</span></div><h3>${esc(p.name)}</h3><p>${p.exercises.slice(0,3).map(x=>esc(findExercise(state,x.exerciseId)?.name)).join(' · ')}${p.exercises.length>3?' + more':''}</p><div class="plan-card-bottom">${button(`Start session ${icon('arrow')}`,'start-plan','text-link',`data-id="${p.id}"`)}${button('Edit','edit-plan','quiet',`data-id="${p.id}"`)}</div></article>`;}
function activeView(){const w=state.draft;const n=w.exercises.flatMap(e=>e.entries).filter(e=>e.done).length;const total=w.exercises.reduce((s,e)=>s+e.entries.length,0);return `${title(w.editingId?'EDITING SAVED WORKOUT':'YOUR ACTIVE SESSION',w.name,`${dateLabel(w.date)} · ${n} of ${total} sets complete`, `<span class="saved-status">${icon('shield')}Autosaved on device</span>`)}<div class="workout-toolbar"><div class="actions">${button('Add exercise +','pick-exercise','secondary')}${button('Session details','session-details','quiet')}</div><div class="actions">${button('Discard','discard','quiet')}${button(w.editingId?'Save changes':'Finish workout','finish','primary')}</div></div>${state.profile.restrictions?`<div class="notice">Your reminder: ${esc(state.profile.restrictions)}</div>`:''}<div class="readiness"><span>${icon('sun')}How are you feeling? <small>Optional</small></span><div class="chips">${[[1,'Low'],[2,'Tired'],[3,'Okay'],[4,'Good'],[5,'Great']].map(([v,l])=>button(l,'readiness',w.readiness===v?'chip selected':'chip',`data-value="${v}" aria-pressed="${w.readiness===v}"`)).join('')}</div></div><div class="workout-list">${w.exercises.map(exerciseCard).join('')}${!w.exercises.length?empty('A blank page, a fresh start','Add an exercise to begin your session.',button('Choose an exercise','pick-exercise','primary')):''}</div><div class="workout-end">${button('Add exercise +','pick-exercise','secondary')}<span>Completed sets count toward your progress.</span>${button(w.editingId?'Save changes':'Finish workout','finish','primary')}</div><div id="rest-timer" class="timer" ${restEnd>Date.now()?'':'hidden'}><span>Rest · <strong id="rest-count"></strong></span>${button('Dismiss','rest-dismiss','quiet')}</div>`;}
function recFor(e){return recommend({exerciseId:e.exerciseId,sessions:state.sessions.filter(w=>w.id!==state.draft?.editingId),goal:state.profile.goal,prescription:e,increment:state.profile.incrementKg,readiness:state.draft?.readiness,auto:state.profile.auto});}
function exerciseCard(e,i){const ex=findExercise(state,e.exerciseId);const r=recFor(e);const last=exposures(state.sessions.filter(w=>w.id!==state.draft?.editingId),e.exerciseId).at(-1);return `<section class="exercise-card" data-exercise="${e.id}"><div class="exercise-heading"><span class="exercise-order">${String(i+1).padStart(2,'0')}</span><div><h2>${esc(ex.name)}</h2><p>${esc(ex.muscle)} · ${esc(ex.equipment)} · ${esc(ex.loadKind)}</p></div>${button('Options','exercise-options','quiet',`data-id="${e.id}"`)}</div><div class="recommendation"><span>${icon('bolt')}</span><div><strong>${r.kg===null?'Find your starting point':`${load(r.kg)} ${unit()} · ${r.sets} × ${r.min}–${r.max}`}</strong><p>${esc(r.reason)}</p><small>${r.evidence} saved exposures · ${r.confidence} confidence · editable coaching suggestion</small></div>${r.kg!==null?button('Use load','apply-rec','quiet',`data-id="${e.id}"`):''}</div><div class="set-table"><div class="set-header"><span>SET</span><span>PREVIOUS</span><span>${unit().toUpperCase()}</span><span>REPS</span><span>RIR <small>opt.</small></span><span class="sr-only">Complete</span></div>${e.entries.map((s,j)=>{const prev=last?.sets[j];return `<div class="set-row ${s.done?'complete':''}"><button class="set-type" data-action="set-type" data-id="${e.id}" data-set="${s.id}" aria-label="Set ${j+1} type: ${s.type}. Change type">${s.type==='working'?j+1:s.type==='warmup'?'W':s.type==='drop'?'D':'F'}</button><span class="previous">${prev?`${load(prev.kg)} × ${prev.reps}`:'—'}</span>${['kg','reps','rir'].map(k=>`<input type="number" inputmode="decimal" min="0" max="${k==='kg'?unit()==='lb'?2204:1000:k==='reps'?200:10}" step="${k==='kg'?'any':'1'}" data-field="${k}" data-id="${e.id}" data-set="${s.id}" aria-label="${esc(ex.name)} set ${j+1} ${k==='kg'?'weight in '+unit():k}" placeholder="—" value="${s[k]===null?'':k==='kg'?load(s.kg):s[k]}">`).join('')}${button(icon('check'),'toggle-set',`complete-button ${s.done?'checked':''}`,`data-id="${e.id}" data-set="${s.id}" aria-label="${s.done?'Uncheck':'Complete'} ${esc(ex.name)} set ${j+1}" aria-pressed="${s.done}"`)}</div>`;}).join('')}</div><div class="exercise-footer">${button('+ Add set','add-set','text-link',`data-id="${e.id}"`)}<span>${e.sets} working sets · target ${e.min}–${e.max} reps</span></div></section>`;}
function programsView(){return `${title('MAKE THE WORK REPEATABLE','Your programs.','A strong foundation. Flexible enough for real life.',`<div class="actions">${button('Generate plans','generate','secondary')}${button('Create program +','new-plan','primary')}</div>`)}<div class="plan-grid">${state.plans.map(planCard).join('')}${!state.plans.length?empty('Your next routine belongs here','Create a manual program, or generate one from your training profile.') :''}</div><div class="section-head"><div><p class="eyebrow">A MOVEMENT FOR EVERY SESSION</p><h2>Exercise library</h2></div>${button('Custom exercise +','custom-exercise','secondary')}</div><label class="search">${icon('workout')}<input id="exercise-search" type="search" aria-label="Search exercise library" placeholder="Find an exercise, muscle, or equipment…"></label><div class="library-list" id="library-results">${library(state).map(e=>`<details class="library-item" data-search="${esc((e.name+' '+e.muscle+' '+e.equipment).toLowerCase())}"><summary><strong>${esc(e.name)}</strong><span>${esc(e.muscle)} · ${esc(e.equipment)}</span></summary><p>${esc(e.cues)}</p><small>${e.compound?'Compound':'Isolation'} · ${esc(e.pattern)} · Log ${esc(e.loadKind)}. No exercise media is bundled.</small></details>`).join('')}</div>`;}
function historyView(){return `${title('EVERY SESSION COUNTS','Your training journal.','A record of the work, exactly as you logged it.',`<a class="text-link" href="#workout">Back to workout ${icon('arrow')}</a>`)}${state.sessions.length?`<div class="history-list">${[...state.sessions].sort((a,b)=>b.date.localeCompare(a.date)||b.startedAt-a.startedAt).map(w=>`<article class="history-item"><div class="history-date"><strong>${new Date(w.date+'T12:00:00').getDate()}</strong><span>${new Date(w.date+'T12:00:00').toLocaleDateString(undefined,{month:'short'})}</span></div><div><h3>${esc(w.name)}</h3><p>${sessionSets(w).length} working sets · ${fmt(load(volume(w)))} ${unit()} × reps · ${w.exercises.length} exercises</p><small>${esc(w.notes)}</small></div><div class="actions">${button('View / edit','edit-session','secondary',`data-id="${w.id}"`)}${button('Delete','delete-session','quiet',`data-id="${w.id}"`)}</div></article>`).join('')}</div>`:empty('Your journal is ready','Finish a workout and it will appear here.',`<a class="primary" href="#workout">Start training</a>`)}`;}
let selectedExercise=null,timeFilter=84,measurementName='Waist',photoLimit=24;
function filteredSessions(){if(!timeFilter)return state.sessions;const start=new Date();start.setDate(start.getDate()-timeFilter);return state.sessions.filter(w=>w.date>=start.toISOString().slice(0,10));}
function progressView(){selectedExercise??=state.sessions.flatMap(w=>w.exercises).find(e=>working(e).length)?.exerciseId||'bench';const sessions=filteredSessions(),all=summary(sessions);const points=strengthPoints(sessions,selectedExercise).map(p=>({...p,value:fromKg(p.value,unit())}));const counts=muscleSets(state,today());const week=state.sessions.filter(w=>w.date>=weekStart(today())&&w.date<=today());const a=achievements(state),unlocked=a.filter(x=>x.unlocked).length;const improved=library(state).filter(e=>{const pts=strengthPoints(week,e.id);return pts.length>1&&pts.at(-1).value>pts[0].value;});return `${title('SEE THE BIGGER PICTURE','The gains dashboard.','Your work, made visible. No guesswork required.')}<div class="metric-row">${metric('SESSIONS',all.workouts,'Selected time range')}${metric('WORKING SETS',fmt(all.sets),'Warm-ups excluded')}${metric('REPETITIONS',fmt(all.reps),'Completed working sets')}${metric('LOAD × REPS',fmt(load(all.volume)),unit()+' · context, not muscle growth')}</div><div class="analytics-grid"><section class="panel"><div class="section-head"><h2>Strength, over time.</h2><span class="badge">ESTIMATED 1RM</span></div><div class="chart-controls">${field('Exercise',`<select id="chart-exercise">${library(state).map(e=>`<option value="${e.id}" ${e.id===selectedExercise?'selected':''}>${esc(e.name)}</option>`).join('')}</select>`)}${field('Time range',`<select id="chart-range">${options({'28':'4 weeks','84':'12 weeks','182':'6 months','365':'1 year','0':'All time'},String(timeFilter))}</select>`)}</div>${chart(points,{label:findExercise(state,selectedExercise)?.name+' · Epley estimated 1RM',unit:unit()})}<p class="chart-note">Estimates use sets of 1–10 reps with external load. Compare the same exercise and equipment; these are not tested maxes.</p>${points.length>1?`<div class="chart-summary"><span>First recorded <strong>${fmt(points[0].value)} ${unit()}</strong></span><span>Latest <strong>${fmt(points.at(-1).value)} ${unit()}</strong></span><span>Change <strong>${fmt((points.at(-1).value/points[0].value-1)*100)}%</strong></span></div>`:''}</section><section class="panel"><div class="section-head"><h2>Where the work went.</h2></div><p class="muted">This week · direct challenging sets</p><div class="muscle-bars">${MUSCLES.map(m=>`<div><span>${m}</span><progress max="${Math.max(12,...Object.values(counts).map(c=>c.direct))}" value="${counts[m]?.direct||0}" aria-label="${m} direct sets"></progress><strong>${counts[m]?.direct||0}</strong></div>`).join('')}</div><details><summary>How we count sets</summary><p>Completed non-warm-up sets at 0–4 RIR, or unknown effort. Secondary muscle work is estimated at 0.5 sets per set: a coaching heuristic, not an exact physiological value.</p><p>${Object.entries(counts).map(([m,c])=>`${m}: ${c.direct} direct + ${c.indirect} estimated indirect`).join(' · ')||'No sets recorded this week.'}</p></details></section></div><section class="weekly-review"><div><p class="eyebrow">YOUR WEEKLY CHECK-IN</p><h2>Keep the bigger picture in mind.</h2></div><div><p>${week.length?`You completed ${week.length} of your ${state.profile.days} planned weekly sessions. ${improved.length?improved.map(e=>esc(e.name)).join(', ')+' improved within this week.':'More comparable exposures will help reveal strength trends.'}`:'No completed sessions this week. Choose a manageable session and start where you are.'}</p><p>${Object.keys(counts).length?`Most direct work: ${esc(Object.entries(counts).sort((a,b)=>b[1].direct-a[1].direct)[0][0])}. `:''}Next priority: ${week.length>=state.profile.days?'Keep your next week sustainable and make room for recovery.':'Follow your schedule; do not add extra sessions just to earn a milestone.'}</p></div></section><div class="section-head"><div><p class="eyebrow">PROGRESS BEYOND THE NUMBERS</p><h2>Your milestones <span class="muted">${unlocked} / ${a.length}</span></h2></div></div><div class="achievement-grid">${a.filter(x=>x.tier===1).map(x=>{const category=a.filter(y=>y.label===x.label);const next=category.find(y=>!y.unlocked)||category.at(-1);return `<article class="achievement ${category.some(y=>y.unlocked)?'unlocked':''}">${icon('trophy')}<h3>${esc(x.label)}</h3><p>${category.filter(y=>y.unlocked).length} / ${category.length} tiers earned</p><progress max="${next.target}" value="${Math.min(next.value,next.target)}" aria-label="${esc(x.label)} progress"></progress><small>${fmt(next.value)} / ${fmt(next.target)} · Tier ${next.tier}</small></article>`;}).join('')}</div><details class="standards panel"><summary>About strength standards</summary><p>Exercise-specific personal progress is available above. Population levels are not shown: no licensed, versioned reference dataset could be verified in this environment. We will not invent thresholds or label machine lifts against universal standards.</p></details>`;}
function bodyView(){const weights=[...state.weights].sort((a,b)=>a.date.localeCompare(b.date));const last=weights.at(-1);const avg=weightTrend(weights,today());const prevDate=new Date();prevDate.setDate(prevDate.getDate()-7);const prev=weightTrend(weights,prevDate.toISOString().slice(0,10));const diff=avg.average!==null&&prev.average!==null?avg.average-prev.average:null;const measurements=state.measurements.filter(m=>m.name===measurementName).sort((a,b)=>a.date.localeCompare(b.date));const measurementNames=[...new Set(['Chest','Waist','Shoulders','Upper arms','Thighs','Hips','Calves',...state.measurements.map(m=>m.name)])];return `${title('MORE THAN A NUMBER','Your body, your perspective.','Private tracking. Meaningful trends. No assumptions about body composition.')}<div class="metric-row">${metric('LATEST WEIGHT',last?`${load(last.kg)} ${unit()}`:'—',last?dateLabel(last.date):'No entries yet')}${metric('7-DAY AVERAGE',avg.average?`${load(avg.average)} ${unit()}`:'—',`${avg.count} actual measurements`)}${metric('WEEKLY AVERAGE CHANGE',diff!==null?`${diff>0?'+':''}${load(diff)} ${unit()}`:'—','Compared to the previous 7 days')}${metric('TARGET',state.profile.targetWeight?`${load(state.profile.targetWeight)} ${unit()}`:'Your choice','Set an optional personal target')}</div><div class="analytics-grid"><section class="panel"><div class="section-head"><h2>Weight history</h2>${button('Log weight +','weight-dialog','secondary')}</div>${chart(weights.map(w=>({date:w.date,value:fromKg(w.kg,unit())})),{label:'Recorded body weight',unit:unit()})}<p class="chart-note">Lines connect recorded weigh-ins; missing days are not filled. Weight change does not measure fat loss.</p><div class="entry-list">${weights.slice(-5).reverse().map(w=>`<div><span>${w.date}</span><strong>${load(w.kg)} ${unit()}</strong>${button('Edit','weight-dialog','quiet',`data-date="${w.date}"`)}</div>`).join('')}</div></section><section class="panel"><div class="section-head"><h2>Measurements</h2>${button('Log +','measure-dialog','secondary')}</div>${field('Measurement',`<select id="measurement-name">${measurementNames.map(n=>`<option ${measurementName===n?'selected':''}>${esc(n)}</option>`).join('')}</select>`)}${chart(measurements.map(m=>({date:m.date,value:unit()==='lb'?m.cm/2.54:m.cm})),{label:measurementName,unit:unit()==='lb'?'in':'cm'})}<div class="entry-list">${measurements.slice(-3).reverse().map(m=>`<div><span>${m.date}</span><strong>${fmt(unit()==='lb'?m.cm/2.54:m.cm)} ${unit()==='lb'?'in':'cm'}</strong>${button('Edit','measure-dialog','quiet',`data-date="${m.date}" data-name="${esc(m.name)}"`)}</div>`).join('')}</div></section></div><div class="section-head"><div><p class="eyebrow">A PICTURE OF YOUR OWN PROGRESS</p><h2>Private photo journal</h2><p class="muted">Stored only on this device. Compare photos side by side below.</p></div>${button('Add photo +','photo-dialog','secondary')}</div><div class="photo-grid">${[...state.photos].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,photoLimit).map(p=>`<figure class="photo-card"><img data-photo="${p.id}" alt="${esc(p.view)} progress photo from ${p.date}" loading="lazy"><figcaption><span><strong>${esc(p.view)}</strong> · ${p.date}</span>${button('Delete','delete-photo','quiet',`data-id="${p.id}"`)}</figcaption></figure>`).join('')}${!state.photos.length?empty('A journal just for you','Add front, side, or back photos when it feels useful. No uploads, ever.'):''}</div>${state.photos.length>photoLimit?button('Show older photos','more-photos','secondary'):''}`;}
async function hydratePhotos(){for(const p of document.querySelectorAll('[data-photo]')){try{const blob=await getPhoto(p.dataset.photo);if(blob&&p.isConnected){const url=URL.createObjectURL(blob);photoURLs.push(url);p.src=url;}}catch(e){notify(e.message,true);}}}
function settingsView(){return `${title('BUILT AROUND YOU','Your training preferences.','Change what’s next. Your history stays yours.')}<div class="settings-grid"><section class="panel"><h2>Training profile</h2><form id="profile-form">${profileFields(state.profile)}<button class="primary" type="submit">Save preferences</button><p class="muted">New goals change future suggestions. Existing plans stay as written; edit or regenerate them when you choose.</p></form></section><div><section class="panel"><h2>Your data belongs to you.</h2><p>Keep a backup somewhere safe. Browser storage can be cleared by your browser or device.</p><div class="stack">${button(`${icon('download')}Export complete JSON backup`,'export-json','secondary')}${button(`${icon('download')}Export workout CSV`,'export-csv','secondary')}${button('Import a backup','import-dialog','secondary')}${button('Request persistent device storage','persist','quiet')}${previous?button('Undo last deletion / discard','undo','secondary'):''}</div><p class="muted">JSON includes your profile, plans, history, drafts, and photos. CSV uses canonical kilograms. Backups are not encrypted.</p></section><section class="panel"><h2>Under the hood</h2><p>Deterministic recommendations, not AI predictions. Conservative double progression, optional effort ratings, and clear reasons.</p><p>Evidence and coaching heuristics are documented in <a href="./docs/RESEARCH.md" target="_blank" rel="noopener">RESEARCH.md</a> in the source release. No ads, trackers, or remote data services.</p><small>Gym Bro 0.1.1 · Local-first PWA · Schema v1</small></section><section class="panel"><h2>Offline availability</h2><p id="offline-status">${navigator.serviceWorker?.controller?'Offline app shell active. Your data stays in IndexedDB.':'Offline shell activates after loading the production build once. Development mode does not cache code.'}</p>${button('Check for app update','update-app','quiet')}<p class="muted">An update waits until all app tabs close. Save your work first. Drafts stay in device storage.</p></section></div></div>`;}
function exerciseById(s,id){const e=s.draft?.exercises.find(e=>e.id===id);if(!e)throw Error('Exercise is no longer in this workout.');return e;}
function picker(replaceId){const choices=replaceId?substitutions(state,exerciseById(state,replaceId).exerciseId):library(state).filter(e=>state.profile.equipment.includes(e.equipment)&&!state.profile.excluded.includes(e.id));dialog(replaceId?'Swap this exercise':'Choose an exercise',`<p>Every exercise keeps its own history. Substitutions do not inherit another movement’s load.</p><label class="search"><input id="picker-search" type="search" aria-label="Filter exercises" placeholder="Search exercises…"></label><div class="picker-list">${choices.map(e=>button(`<span><strong>${esc(e.name)}</strong><small>${esc(e.muscle)} · ${esc(e.equipment)}</small></span>${icon('plus')}`,'choose-exercise','picker-item',`data-id="${e.id}" ${replaceId?`data-replace="${replaceId}"`:''} data-search="${esc((e.name+' '+e.muscle).toLowerCase())}"`)).join('')||'<p>No matching alternatives in your equipment. Edit your profile or add a custom exercise.</p>'}</div>`);}
function planEditor(id){const p=state.plans.find(p=>p.id===id)||{id:uid(),name:'My program',exercises:[]};dialog(id?'Edit program':'Create a program',`<form id="plan-form" data-id="${p.id}">${field('Program name',`<input name="name" maxlength="80" required value="${esc(p.name)}">`)}<p class="muted">Choose movements you can perform comfortably. These prescriptions stay editable.</p><div id="plan-rows">${p.exercises.map(planRow).join('')}</div><div class="actions">${button('+ Add exercise','plan-add-row','secondary')}<button type="submit" class="primary">Save program</button></div>${id?button('Delete program','delete-plan','quiet',`data-id="${id}"`):''}</form>`);}
function planRow(e={exerciseId:library(state)[0].id,sets:2,min:6,max:10}){return `<div class="plan-edit-row">${field('Exercise',`<select name="exerciseId">${library(state).map(x=>`<option value="${x.id}" ${x.id===e.exerciseId?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`)}<div class="form-grid three">${field('Sets',`<input name="sets" type="number" min="1" max="12" required value="${e.sets}">`)}${field('Min reps',`<input name="min" type="number" min="1" max="100" required value="${e.min}">`)}${field('Max reps',`<input name="max" type="number" min="1" max="100" required value="${e.max}">`)}</div>${button('Remove','plan-remove-row','quiet')}</div>`;}
function exerciseOptions(id){const e=exerciseById(state,id);const ex=findExercise(state,e.exerciseId);dialog(ex.name,`<p>${esc(ex.cues)}</p><div class="stack">${button('Copy first weight to all sets','copy-kg','secondary',`data-id="${id}"`)}${button('Copy first reps to all sets','copy-reps','secondary',`data-id="${id}"`)}${button('Check all sets','check-all','secondary',`data-id="${id}"`)}${button('Uncheck all sets','uncheck-all','secondary',`data-id="${id}"`)}${button('Substitute exercise','swap','secondary',`data-id="${id}"`)}${button('Move exercise up','move-up','secondary',`data-id="${id}"`)}${button('Move exercise down','move-down','secondary',`data-id="${id}"`)}${button('Edit targets & notes','exercise-details','secondary',`data-id="${id}"`)}${button('Remove last set','remove-set','quiet',`data-id="${id}"`)}${button('Remove exercise','remove-exercise','quiet',`data-id="${id}"`)}</div>`);}
const actions={
 close:closeDialog,
 'more-photos':()=>{photoLimit+=24;render();},
 reload:()=>location.reload(),
 'start-empty':()=>startWorkout(),
 'start-plan':b=>startWorkout(state.plans.find(p=>p.id===b.dataset.id)),
 'new-plan':()=>planEditor(),
 'edit-plan':b=>planEditor(b.dataset.id),
 'plan-add-row':()=>document.querySelector('#plan-rows').insertAdjacentHTML('beforeend',planRow()),
 'plan-remove-row':b=>b.closest('.plan-edit-row').remove(),
 'delete-plan':b=>confirmAction('Delete program?','Saved workouts will remain in your journal. You can undo this deletion.','confirm-delete-plan',`data-id="${b.dataset.id}"`),
 'confirm-delete-plan':async b=>{await queued(s=>{s.plans=s.plans.filter(p=>p.id!==b.dataset.id);},{undo:true});closeDialog();notify('Program deleted. Undo is available in Settings.');},
 generate:()=>confirmAction('Generate new programs?','New routines will be added using your profile, goal, equipment, and time budget. Existing programs will stay. Review personal exercise restrictions before training.','confirm-generate'),
 'confirm-generate':async()=>{await queued(s=>{s.plans.push(...generatePlans(s));});closeDialog();notify('Programs added. Edit any prescription to suit you.');},
 'pick-exercise':()=>picker(),
 'choose-exercise':async b=>{await queued(s=>{const [min,max]=goalRange(s.profile.goal);const p={exerciseId:b.dataset.id,sets:2,min,max};const e=makeDraft({name:'',exercises:[p]},today()).exercises[0];if(b.dataset.replace){const index=s.draft.exercises.findIndex(e=>e.id===b.dataset.replace);s.draft.exercises[index]=e;}else s.draft.exercises.push(e);},{undo:!!b.dataset.replace});closeDialog();},
 'exercise-options':b=>exerciseOptions(b.dataset.id),
 swap:b=>picker(b.dataset.id),
 'add-set':async b=>queued(s=>{const e=exerciseById(s,b.dataset.id);e.entries.push({id:uid(),kg:null,reps:null,rir:null,done:false,type:'working'});}),
 'remove-set':b=>confirmAction('Remove the last set?','This removes the last set from this exercise, including any logged values.','confirm-remove-set',`data-id="${b.dataset.id}"`),
 'confirm-remove-set':async b=>{await queued(s=>{exerciseById(s,b.dataset.id).entries.pop();},{undo:true});closeDialog();},
 'remove-exercise':b=>confirmAction('Remove exercise?','Its sets will be removed from this draft. Saved history remains unchanged.','confirm-remove-exercise',`data-id="${b.dataset.id}"`),
 'confirm-remove-exercise':async b=>{await queued(s=>{s.draft.exercises=s.draft.exercises.filter(e=>e.id!==b.dataset.id);},{undo:true});closeDialog();},
 'move-up':b=>moveExercise(b.dataset.id,-1),
 'move-down':b=>moveExercise(b.dataset.id,1),
 'copy-kg':b=>copySets(b.dataset.id,'kg'),
 'copy-reps':b=>copySets(b.dataset.id,'reps'),
 'check-all':async b=>{await queued(s=>{for(const a of exerciseById(s,b.dataset.id).entries){if(a.kg===null||a.reps===null||a.reps<1)throw Error('Enter a load and reps for every set before checking all.');a.done=true;}});closeDialog();},
 'uncheck-all':async b=>{await queued(s=>{exerciseById(s,b.dataset.id).entries.forEach(a=>a.done=false);});closeDialog();},
 'toggle-set':async b=>{let checked=false;await queued(s=>{const a=exerciseById(s,b.dataset.id).entries.find(x=>x.id===b.dataset.set);if(!a.done&&(a.kg===null||a.reps===null||a.reps<1))throw Error('Enter a load and at least one repetition first. For unweighted bodyweight sets, enter 0.');a.done=!a.done;checked=a.done;});if(checked&&state.profile.timer)startRest();},
 'set-type':b=>{const e=exerciseById(state,b.dataset.id);const a=e.entries.find(a=>a.id===b.dataset.set);dialog('Set type',`<p>Warm-ups are recorded separately and excluded from progression and working-set totals.</p><div class="stack">${['working','warmup','drop','failure'].map(t=>button(t[0].toUpperCase()+t.slice(1),'choose-type',a.type===t?'primary':'secondary',`data-id="${e.id}" data-set="${a.id}" data-value="${t}"`)).join('')}</div>`);},
 'choose-type':async b=>{await queued(s=>{exerciseById(s,b.dataset.id).entries.find(a=>a.id===b.dataset.set).type=b.dataset.value;});closeDialog();},
 'apply-rec':async b=>{await queued(s=>{const e=exerciseById(s,b.dataset.id);const r=recFor(e);if(r.kg===null)return;for(const a of e.entries.filter(a=>!a.done))a.kg=r.kg;});notify('Suggested load applied to unfinished sets. Edit it any time.');},
 readiness:async b=>queued(s=>{s.draft.readiness=s.draft.readiness===Number(b.dataset.value)?null:Number(b.dataset.value);}),
 discard:()=>confirmAction('Discard this draft?','Your saved workouts will remain. You can undo this discard in Settings.','confirm-discard'),
 'confirm-discard':async()=>{await queued(s=>{s.draft=null;},{undo:true});closeDialog();},
 finish:async()=>{await queue;const w=state.draft;if(!w.exercises.some(e=>e.entries.some(a=>a.done)))throw Error('Complete at least one set before saving the workout.');const incomplete=w.exercises.some(e=>e.entries.some(a=>!a.done));if(incomplete)confirmAction('Finish with incomplete sets?','Only checked sets will count toward recommendations and analytics. Unchecked values are preserved in history for reference.','confirm-finish');else await finishWorkout();},
 'confirm-finish':finishWorkout,
 'session-details':()=>dialog('Session details',`<form id="session-form">${field('Workout name',`<input name="name" required maxlength="80" value="${esc(state.draft.name)}">`)}${field('Training date',`<input name="date" type="date" required max="${today()}" value="${state.draft.date}">`)}${field('Session notes',`<textarea name="notes" maxlength="3000">${esc(state.draft.notes)}</textarea>`)}<button class="primary" type="submit">Save details</button></form>`),
 'exercise-details':b=>{const e=exerciseById(state,b.dataset.id);dialog('Targets & notes',`<form id="exercise-form" data-id="${e.id}"><div class="form-grid three">${field('Target sets',`<input name="sets" type="number" min="1" max="12" value="${e.sets}" required>`)}${field('Min reps',`<input name="min" type="number" min="1" max="100" value="${e.min}" required>`)}${field('Max reps',`<input name="max" type="number" min="1" max="100" value="${e.max}" required>`)}</div>${field('Exercise notes',`<textarea name="notes" maxlength="1000">${esc(e.notes)}</textarea>`)}<p class="muted">Changing target sets does not add or delete logged sets. Use Add set / Remove set.</p><button type="submit" class="primary">Save targets</button></form>`);},
 'edit-session':async b=>{if(state.draft)throw Error('Finish or discard the active draft before editing history.');await queued(s=>{const w=structuredClone(s.sessions.find(w=>w.id===b.dataset.id));w.editingId=w.id;s.draft=w;});go('workout');},
 'delete-session':b=>confirmAction('Delete this session?','This removes it from your training history and future recommendations. You can undo this deletion.','confirm-delete-session',`data-id="${b.dataset.id}"`),
 'confirm-delete-session':async b=>{await queued(s=>{if(s.draft?.editingId===b.dataset.id)throw Error('Close the edit draft first.');s.sessions=s.sessions.filter(w=>w.id!==b.dataset.id);},{undo:true});closeDialog();notify('Workout deleted. Undo is available in Settings.');},
 undo:async()=>{if(!previous)return;const restored=previous;await queued(s=>{Object.keys(s).forEach(k=>delete s[k]);Object.assign(s,restored);});previous=null;render();notify('Last deletion undone.');},
 'custom-exercise':()=>dialog('Add a custom exercise',`<form id="custom-form">${field('Exercise name',`<input name="name" required maxlength="80">`)}${field('Primary muscle',`<select name="muscle">${MUSCLES.map(m=>`<option>${m}</option>`).join('')}</select>`)}${field('Movement pattern',`<select name="pattern">${[...new Set(EXERCISES.map(e=>e.pattern))].map(m=>`<option>${m}</option>`).join('')}</select>`)}${field('Equipment',`<select name="equipment">${options({barbell:'Barbell',dumbbell:'Dumbbell',machine:'Machine',cable:'Cable',bodyweight:'Bodyweight'})}</select>`)}${field('Technique notes',`<textarea name="cues" maxlength="1000"></textarea>`)}<label class="toggle"><input name="compound" type="checkbox">Compound movement</label><button type="submit" class="primary">Save exercise</button></form>`),
 'weight-dialog':b=>{const date=b.dataset.date||today(),w=state.weights.find(w=>w.date===date);dialog(w?'Edit weigh-in':'Log your weight',`<form id="weight-form">${field('Date',`<input name="date" type="date" max="${today()}" required value="${date}">`)}${field('Weight ('+unit()+')',`<input name="value" type="number" min="${unit()==='lb'?44.1:20}" max="${unit()==='lb'?1102:500}" step="any" required value="${w?load(w.kg):''}">`)}${field('Optional target weight ('+unit()+')',`<input name="target" type="number" step="any" min="${unit()==='lb'?44.1:20}" max="${unit()==='lb'?1102:500}" value="${state.profile.targetWeight?load(state.profile.targetWeight):''}">`)}<p class="muted">One entry per date. Saving on an existing date updates that entry.</p><button type="submit" class="primary">Save weigh-in</button>${w?button('Delete entry','delete-weight','quiet',`data-date="${date}"`):''}</form>`);},
 'delete-weight':async b=>{await queued(s=>{s.weights=s.weights.filter(w=>w.date!==b.dataset.date);},{undo:true});closeDialog();},
 'measure-dialog':b=>{const date=b.dataset.date||today(),name=b.dataset.name||measurementName,m=state.measurements.find(m=>m.date===date&&m.name===name);dialog('Log a measurement',`<form id="measure-form">${field('Date',`<input name="date" type="date" required max="${today()}" value="${date}">`)}${field('Measurement name',`<input name="name" list="measurement-options" maxlength="60" required value="${esc(name)}"><datalist id="measurement-options">${['Chest','Waist','Shoulders','Upper arms','Thighs','Hips','Calves'].map(n=>`<option>${n}</option>`).join('')}</datalist>`)}${field('Measurement ('+(unit()==='lb'?'in':'cm')+')',`<input name="value" type="number" step="any" min="0.5" max="${unit()==='lb'?196:500}" required value="${m?unit()==='lb'?Number((m.cm/2.54).toFixed(2)):m.cm:''}">`)}<button type="submit" class="primary">Save measurement</button>${m?button('Delete entry','delete-measure','quiet',`data-date="${date}" data-name="${esc(name)}"`):''}</form>`);},
 'delete-measure':async b=>{await queued(s=>{s.measurements=s.measurements.filter(m=>!(m.date===b.dataset.date&&m.name===b.dataset.name));},{undo:true});closeDialog();},
 'photo-dialog':()=>dialog('A moment in your progress',`<form id="photo-form">${field('Photo date',`<input name="date" type="date" max="${today()}" required value="${today()}">`)}${field('View',`<select name="view">${options({front:'Front',side:'Side',back:'Back'})}</select>`)}${field('Photo (JPEG, PNG, WebP · up to 8 MB)',`<input name="photo" type="file" accept="image/jpeg,image/png,image/webp" required>`)}<p class="muted">Saved privately in this browser, with no server upload. Original files may include camera metadata; JSON backups include the original file.</p><button type="submit" class="primary">Save photo on device</button></form>`),
 'delete-photo':b=>confirmAction('Delete this photo?','This removes the photo permanently from this device. Export a backup first if you want to keep a copy.','confirm-delete-photo',`data-id="${b.dataset.id}"`),
 'confirm-delete-photo':async b=>{await queued(s=>{s.photos=s.photos.filter(p=>p.id!==b.dataset.id);});await deletePhoto(b.dataset.id);previous=null;closeDialog();},
 'export-json':async()=>{await queue;download(`gymbro-backup-${today()}.json`,await exportBackup(state));notify('Complete backup exported. Store it somewhere safe.');},
 'export-csv':async()=>{await queue;download(`gymbro-workouts-${today()}.csv`,exportCSV(state,findExercise),'text/csv');},
 'import-dialog':()=>{imported=null;dialog('Import your workouts',`<p>Select a Gym Bro 2.0 backup or an original Gym Bro v3 complete JSON export. Original-app history is merged with your current journal. A Gym Bro 2.0 backup uses full replacement after preview.</p><form id="import-form">${field('Gym Bro JSON backup',`<input name="backup" type="file" accept="application/json,.json" required>`)}<button type="submit" class="primary">Validate & preview</button></form>`);},
 'confirm-import':async()=>{if(!imported)return;await queue;if(imported.mode==='legacy'){if(state!==imported.baseState)throw Error('Your journal changed after this preview. Choose the file again to refresh the merge.');if(!document.querySelector('#legacy-kg-confirm')?.checked)throw Error('Confirm that the original export uses kilograms before merging.');}const wasLegacy=imported.mode==='legacy';await restoreState(imported.state,imported.photos);state=imported.state;imported=null;previous=null;closeDialog();render();notify(wasLegacy?'Original workouts merged into your history.':'Backup restored.');if(wasLegacy)go('history');},
 persist:async()=>{const granted=await navigator.storage?.persist?.();notify(granted?'Persistent storage granted. Keep external backups too.':'This browser did not grant persistent storage. Keep a JSON backup.');},
 'update-app':async()=>{const r=await navigator.serviceWorker?.getRegistration();if(!r){notify('Use the production build to enable offline caching.');return;}await r.update();notify(r.waiting?'Update downloaded. Close all app tabs and reopen to activate.':'Update check complete.');},
 'rest-dismiss':()=>{restEnd=0;clearInterval(restInterval);document.querySelector('#rest-timer')?.setAttribute('hidden','');}
};
async function startWorkout(plan){if(state.draft){go('workout');return;}await queued(s=>{s.draft=makeDraft(plan,today());});go('workout');}
async function finishWorkout(){await queued(s=>{const w=s.draft;if(!w||!w.exercises.some(e=>e.entries.some(a=>a.done)))throw Error('Complete at least one set first.');const saved={...w,finishedAt:Date.now()};delete saved.editingId;if(w.editingId){const i=s.sessions.findIndex(x=>x.id===w.editingId);if(i<0)throw Error('The original session is missing.');s.sessions[i]=saved;}else s.sessions.push(saved);s.draft=null;});closeDialog();restEnd=0;clearInterval(restInterval);notify('Workout saved. That’s work worth showing up for.');go('history');}
async function moveExercise(id,offset){await queued(s=>{const i=s.draft.exercises.findIndex(e=>e.id===id),j=i+offset;if(j<0||j>=s.draft.exercises.length)return;[s.draft.exercises[i],s.draft.exercises[j]]=[s.draft.exercises[j],s.draft.exercises[i]];});closeDialog();}
async function copySets(id,key){await queued(s=>{const e=exerciseById(s,id);if(!e.entries.length||e.entries[0][key]===null)throw Error('Fill the first set first.');for(const a of e.entries)a[key]=e.entries[0][key];});closeDialog();notify('First-set value copied.');}
function startRest(){restEnd=Date.now()+state.profile.restSeconds*1000;clearInterval(restInterval);const tick=()=>{const el=document.querySelector('#rest-timer');if(!el)return;if(restEnd<=Date.now()){el.hidden=true;clearInterval(restInterval);notify('Rest timer finished. Continue when you’re ready.');return;}el.hidden=false;const n=Math.ceil((restEnd-Date.now())/1000);document.querySelector('#rest-count').textContent=`${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`;};tick();restInterval=setInterval(tick,1000);}
document.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b)return;try{if(['finish','toggle-set','check-all'].includes(b.dataset.action)&&document.querySelector('.set-table input:invalid, .set-table input[aria-invalid="true"]'))throw Error('Correct the highlighted set values before completing or saving.');b.disabled=true;await actions[b.dataset.action]?.(b);}catch(e){notify(e.message,true);}finally{if(b.isConnected)b.disabled=false;}});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='exercise-search'||el.id==='picker-search'){const root=el.id==='exercise-search'?document.querySelector('#library-results'):document.querySelector('.picker-list');for(const item of root.querySelectorAll('[data-search]'))item.hidden=!item.dataset.search.includes(el.value.toLowerCase());}
 if(!el.dataset.field)return;
 const value=el.value===''?null:Number(el.value);if(value!==null&&(!el.validity.valid||!Number.isFinite(value))){el.setAttribute('aria-invalid','true');return;}el.removeAttribute('aria-invalid');const id=el.dataset.id,set=el.dataset.set,key=el.dataset.field;
 queued(s=>{const a=exerciseById(s,id).entries.find(a=>a.id===set);a[key]=key==='kg'&&value!==null?toKg(value,s.profile.unit):value;if(value===null||key==='reps'&&value<1)a.done=false;},{draw:false}).catch(()=>el.setAttribute('aria-invalid','true'));
});
document.addEventListener('change',event=>{const el=event.target;if(el.name==='unit'&&el.dataset.currentUnit){const increment=el.form?.querySelector('[name="increment"]');if(increment)increment.value=displayLoad(toKg(Number(increment.value),el.dataset.currentUnit),el.value);el.dataset.currentUnit=el.value;}if(el.id==='chart-exercise'){selectedExercise=el.value;render();}if(el.id==='chart-range'){timeFilter=Number(el.value);render();}if(el.id==='measurement-name'){measurementName=el.value;render();}});
function readProfile(f,previousProfile){const d=new FormData(f),unit=d.get('unit');return {name:d.get('name').trim(),goal:d.get('goal'),experience:d.get('experience'),days:Number(d.get('days')),minutes:Number(d.get('minutes')),split:d.get('split'),unit,incrementKg:toKg(Number(d.get('increment')),unit),equipment:d.getAll('equipment'),secondaryGoals:d.get('secondaryGoal')?[d.get('secondaryGoal')]:[],priorities:d.get('priority')?[d.get('priority')]:[],trainingDays:d.getAll('trainingDays'),restrictions:d.get('restrictions'),excluded:d.getAll('excluded'),auto:d.has('auto'),timer:d.has('timer'),restSeconds:Number(d.get('restSeconds')),targetWeight:previousProfile?.targetWeight??null};}
document.addEventListener('submit',async event=>{const f=event.target;if(!f.id)return;event.preventDefault();if(!f.reportValidity())return;const submit=f.querySelector('[type="submit"]');if(submit)submit.disabled=true;try{const d=new FormData(f);switch(f.id){
 case 'onboard-form':case 'profile-form':{const profile=readProfile(f,state.profile);const first=f.id==='onboard-form';await queued(s=>{s.profile=profile;if(first&&profile.split!=='custom')s.plans=generatePlans(s);});notify(first?'Your training space is ready.':'Preferences saved. Your history is unchanged.');break;}
 case 'plan-form':{const exercises=[...f.querySelectorAll('.plan-edit-row')].map(row=>Object.fromEntries([...row.querySelectorAll('select,input')].map(x=>[x.name,x.name==='exerciseId'?x.value:Number(x.value)])));if(!exercises.length)throw Error('Add at least one exercise.');await queued(s=>{const p={id:f.dataset.id,name:d.get('name').trim(),exercises};if(!p.name)throw Error('Give the program a name.');const index=s.plans.findIndex(x=>x.id===p.id);if(index<0)s.plans.push(p);else s.plans[index]=p;});closeDialog();break;}
 case 'session-form':await queued(s=>{s.draft.name=d.get('name').trim();s.draft.date=d.get('date');s.draft.notes=d.get('notes');});closeDialog();break;
 case 'exercise-form':await queued(s=>{const e=exerciseById(s,f.dataset.id);for(const k of ['sets','min','max'])e[k]=Number(d.get(k));e.notes=d.get('notes');});closeDialog();break;
 case 'custom-form':await queued(s=>{const equipment=d.get('equipment');s.customExercises.push({id:uid(),name:d.get('name').trim(),muscle:d.get('muscle'),pattern:d.get('pattern'),equipment,secondary:[],compound:d.has('compound'),loadKind:equipment==='dumbbell'?'per dumbbell':equipment==='bodyweight'?'added load':'total load',cues:d.get('cues'),unilateral:false,difficulty:'user-defined'});});closeDialog();break;
 case 'weight-form':await queued(s=>{const date=d.get('date'),kg=toKg(Number(d.get('value')),s.profile.unit);s.weights=s.weights.filter(w=>w.date!==date);s.weights.push({date,kg});s.profile.targetWeight=d.get('target')?toKg(Number(d.get('target')),s.profile.unit):null;});closeDialog();break;
 case 'measure-form':await queued(s=>{const name=d.get('name').trim(),date=d.get('date'),cm=Number(d.get('value'))*(s.profile.unit==='lb'?2.54:1);if(!name)throw Error('Name this measurement.');s.measurements=s.measurements.filter(m=>!(m.date===date&&m.name===name));s.measurements.push({date,name,cm});measurementName=name;});closeDialog();break;
 case 'photo-form':{const file=d.get('photo');if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8*1024*1024)throw Error('Choose a JPEG, PNG, or WebP image no larger than 8 MB.');const bitmap=await createImageBitmap(file);if(bitmap.width*bitmap.height>20000000){bitmap.close();throw Error('Choose an image of no more than 20 megapixels.');}bitmap.close();const id=uid();await putPhoto(id,file);try{await queued(s=>{s.photos.push({id,date:d.get('date'),view:d.get('view')});});}catch(e){await deletePhoto(id);throw e;}closeDialog();break;}
 case 'import-form':{const file=d.get('backup');if(file.size>100*1024*1024)throw Error('Backup exceeds 100 MB.');imported=null;const raw=await file.text();let source;try{source=JSON.parse(raw);}catch{throw Error('This file is not valid JSON.');}await queue;if(source?.type==='muscle-workout-backup'){const baseState=state;imported=await prepareLegacyImport(source,baseState);imported.baseState=baseState;const r=imported.report;dialog('Merge original Gym Bro history',`<p><strong>${r.addedWorkouts} workouts ready</strong> · ${r.addedSets} working sets · ${r.addedWeights} weigh-ins · ${r.addedPlans} programs.</p><p>${r.skippedWorkouts} matching workouts skipped. Your current workouts, active draft, profile, measurements, and photos are kept. ${r.weightConflicts?`${r.weightConflicts} same-date weight conflicts: your current entries will be kept.`:''}</p><p>Original session dates and logged loads/reps are preserved. Warm-up checkboxes are saved as session notes; individual set types and RIR were not recorded. Profile increment settings control future suggestions.</p><label class="toggle"><input id="legacy-kg-confirm" type="checkbox">I confirm the original export uses kilograms (kg).</label><div class="actions">${button('Cancel','close','secondary')}${button('Merge into history','confirm-import','primary')}</div>`);break;}imported=parseBackup(raw);for(const p of imported.photos){const bitmap=await createImageBitmap(p.blob);if(bitmap.width*bitmap.height>20000000){bitmap.close();throw Error('An image exceeds the 20 megapixel limit.');}bitmap.close();}const duplicate=imported.state.sessions.filter(w=>state.sessions.some(x=>x.id===w.id)).length;dialog('Review your backup',`<p>${imported.state.sessions.length} workouts · ${imported.state.plans.length} programs · ${imported.state.weights.length} weigh-ins · ${imported.photos.length} photos.</p><p>${duplicate} workout IDs already exist here. This is a full replacement, not a merge; duplicates will not be added.</p><p><strong>Your current journal will be replaced.</strong> Export it first if needed.</p><div class="actions">${button('Cancel','close','secondary')}${button('Replace & restore backup','confirm-import','danger')}</div>`);break;}
 }}catch(e){notify(e.message,true);}finally{if(submit?.isConnected)submit.disabled=false;}});
async function boot(){try{if(navigator.locks){await new Promise((resolve,reject)=>{navigator.locks.request('gymbro-writer',{ifAvailable:true},async lock=>{if(!lock){reject(Error('Gym Bro is already open in another tab. Close that tab, then reload here to prevent conflicting writes.'));return;}resolve();await new Promise(done=>window.addEventListener('pagehide',done,{once:true}));}).catch(reject);});}await openDB();state=await loadState();render();if('serviceWorker'in navigator&&document.querySelector('meta[name="production"]')){const r=await navigator.serviceWorker.register('./sw.js',{scope:'./'});if(r.waiting)notify('An update is ready. Close all tabs to activate after saving.');}}catch(e){app.innerHTML=`<main class="storage-error"><h1>Your journal couldn’t open.</h1><p>${esc(e.message)}</p><p>Your stored data has not been reset. Check browser storage permissions or try again in a regular browser window.</p><button type="button" data-action="reload">Reload</button></main>`;}}
boot();
